const paths = [".worktrees/bvhviewer-main", ".worktrees/bvhviewer-gui", ".worktrees/bvhviewer-playback-range"];
for (const path of paths) {
  const r = await tools.exec_command({
    cmd: `git worktree remove ${path}`,
    workdir: "/Volumes/teaching/Code/PyNGLDemos",
    yield_time_ms: 30000,
    max_output_tokens: 12000,
    sandbox_permissions: "require_escalated",
    justification: `May I remove the clean, merged ${path} worktree while preserving its branch?`,
    prefix_rule: ["git", "worktree", "remove"]
  });
  text(`${path}: ${r.output || "removed"}`);
  if (r.exit_code !== 0) break;
}
